using System.Collections.Concurrent;
using System.Diagnostics;
using System.Text;
using System.Text.Json;
using DCode.Server.Projects;
using DCode.Server.Tools;

namespace DCode.Server.Runs;

public sealed class RunExecutionService
{
    private readonly RunRepository _repository;private readonly ProjectService _projects;private readonly ConcurrentDictionary<string,ManagedProcess> _running=new();
    public RunExecutionService(RunRepository repository,ProjectService projects){_repository=repository;_projects=projects;_repository.MarkInterrupted();}

    public IReadOnlyList<RunConfiguration> ListConfigurations(string projectId){var project=_projects.GetProject(projectId);EnsureDetected(project);return _repository.ListConfigurations(projectId);}
    public RunConfiguration Save(string projectId,string? id,SaveRunConfigurationRequest request){var project=_projects.GetProject(projectId);ValidateWorkingDirectory(project,request.WorkingDirectory);return _repository.Save(projectId,id,request);}
    public void Delete(string projectId,string id){_projects.GetProject(projectId);if(_running.Values.Any(item=>item.ConfigurationId==id))throw new InvalidOperationException("Stop the running command before deleting its configuration.");_repository.Delete(projectId,id);}
    public RunExecution Start(string projectId,string configurationId){var project=_projects.GetProject(projectId);var configuration=_repository.GetConfiguration(projectId,configurationId);if(_running.Values.Any(item=>item.ConfigurationId==configurationId))throw new InvalidOperationException("This run configuration is already running.");var working=ValidateWorkingDirectory(project,configuration.WorkingDirectory);var execution=_repository.StartExecution(configuration,Path.GetRelativePath(project.Path,working));var launch=ProcessLaunchResolver.Resolve(configuration.Command,configuration.Arguments);var start=new ProcessStartInfo{FileName=launch.Executable,WorkingDirectory=working,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var argument in launch.Arguments)start.ArgumentList.Add(argument);var process=new Process{StartInfo=start,EnableRaisingEvents=true};var managed=new ManagedProcess(configuration.Id,process);if(!_running.TryAdd(execution.Id,managed))throw new InvalidOperationException("Unable to register command execution.");process.OutputDataReceived+=(_,eventArgs)=>Append(execution.Id,managed,managed.Stdout,eventArgs.Data);process.ErrorDataReceived+=(_,eventArgs)=>Append(execution.Id,managed,managed.Stderr,eventArgs.Data);try{if(!process.Start())throw new InvalidOperationException("The command process did not start.");process.BeginOutputReadLine();process.BeginErrorReadLine();_ = MonitorAsync(execution.Id,managed);return _repository.GetExecution(execution.Id);}catch(Exception exception){_running.TryRemove(execution.Id,out _);process.Dispose();_repository.Complete(execution.Id,"failed","","",null,exception.Message);throw new InvalidOperationException($"Unable to start '{configuration.Name}': {exception.Message}",exception);}}
    public RunExecution Stop(string projectId,string executionId){_projects.GetProject(projectId);var execution=_repository.GetExecution(executionId);if(execution.ProjectId!=projectId)throw new KeyNotFoundException("Run execution was not found.");if(!_running.TryGetValue(executionId,out var managed))return execution;managed.StopRequested=true;try{if(!managed.Process.HasExited)managed.Process.Kill(entireProcessTree:true);}catch(InvalidOperationException){}return _repository.GetExecution(executionId);}
    public IReadOnlyList<RunExecution> ListExecutions(string projectId){_projects.GetProject(projectId);return _repository.ListExecutions(projectId);}
    private async Task MonitorAsync(string id,ManagedProcess managed){try{await managed.Process.WaitForExitAsync();managed.Process.WaitForExit();var stdout=Read(managed.Stdout);var stderr=Read(managed.Stderr);_repository.Complete(id,managed.StopRequested?"stopped":managed.Process.ExitCode==0?"completed":"failed",stdout,stderr,managed.Process.ExitCode,managed.StopRequested?null:managed.Process.ExitCode==0?null:$"Command exited with code {managed.Process.ExitCode}.");}catch(Exception exception){_repository.Complete(id,"failed",Read(managed.Stdout),Read(managed.Stderr),null,exception.Message);}finally{_running.TryRemove(id,out _);managed.Process.Dispose();}}
    private void Append(string id,ManagedProcess managed,StringBuilder target,string? line){if(line is null)return;lock(target){if(target.Length<1_000_000)target.AppendLine(line);}_repository.UpdateOutput(id,Read(managed.Stdout),Read(managed.Stderr));}
    private static string Read(StringBuilder value){lock(value)return value.ToString();}
    private static string ValidateWorkingDirectory(ProjectInfo project,string? requested){var path=ProjectPathSandbox.Resolve(new ToolContext(project.Id,project.Path,project.Path,CancellationToken.None),requested??".");if(!Directory.Exists(path))throw new DirectoryNotFoundException($"Working directory not found: {requested}");return path;}
    private void EnsureDetected(ProjectInfo project){if(_repository.ListConfigurations(project.Id).Count>0)return;var packagePath=Path.Combine(project.Path,"package.json");if(!File.Exists(packagePath))return;try{using var document=JsonDocument.Parse(File.ReadAllText(packagePath));if(!document.RootElement.TryGetProperty("scripts",out var scripts)||scripts.ValueKind!=JsonValueKind.Object)return;foreach(var script in scripts.EnumerateObject())_repository.Save(project.Id,null,new($"npm: {script.Name}","npm",["run",script.Name],"."),detected:true);}catch(JsonException){}}
    private sealed class ManagedProcess(string configurationId,Process process){public string ConfigurationId{get;}=configurationId;public Process Process{get;}=process;public StringBuilder Stdout{get;}=new();public StringBuilder Stderr{get;}=new();public bool StopRequested{get;set;}}
}
